import { readFile, writeFile } from 'node:fs/promises'
import { createHash } from 'node:crypto'
import { compileWelcome } from './portable.mjs'

const source = await readFile(new URL('../shared/Welcome.lite.tsx', import.meta.url), 'utf8')
const { swift, vue, tokens } = await compileWelcome(source, '__MAVIS_THEME__')
// Validate both targets before replacing generated files. Never edit these outputs.
const header = `Generated by Mitosis 0.14.2 + Mavis experimental adapters; source SHA256 ${createHash('sha256').update(source).digest('hex')}`
await writeFile(
  new URL('../native/Sources/MavisDesktop/Welcome.generated.swift', import.meta.url),
  `// ${header}\n${swift}\n${tokens}\n`,
)
await writeFile(
  new URL('../web/Welcome.generated.vue', import.meta.url),
  `<!-- ${header} -->\n${vue}\n`,
)
console.log('Generated Vue and SwiftUI from shared/Welcome.lite.tsx.')
